NEW_FILES = {'tests/test_wall_pilaster.py': '"""wall_pilaster: minted 2026-10-30 by tools/new_species.py (roadmap 150)."""\nimport pytest\n\nfrom zoo_keeper.core import genome, kit\n\n\ndef test_wall_pilaster_is_discovered_and_validates():\n    assert "wall_pilaster" in genome.list_species()\n    assert genome.validate_genome(genome.load_species("wall_pilaster")) == []\n\n\ndef test_wall_pilaster_plans_at_its_authored_dims():\n    plan = kit.plan_kit({"building_id": "t", "slots": [{\n        "slot_id": "wall_pilaster_0", "role": "prop", "size_mod": "full", "style": 1,\n        "species": "wall_pilaster",\n        "fit": {"dims": [0.6, 0.1, 7.0], "pivot": "center"}}]},\n        theme="delco", style=1)\n    assert plan["species_fallbacks"] == []\n    assert plan["modules"][0]["species"] == "wall_pilaster"\n\n\ndef test_the_pier_is_the_slots_box_exactly_and_its_shaft_stands_back():\n    """FAILS ON 1.149.0: no species. Plinth and cap fill the slot; the shaft is narrower and set back from their\n    front (local -Y), its back on the wall (+Y)."""\n    from zoo_keeper.core import pilaster_forms as P\n    w, d, h = 0.6, 0.1, 7.2\n    parts = {n: (lo, hi) for n, lo, hi in P.boxes(w, d, h)}\n    lo = [min(b[0][i] for b in parts.values()) for i in range(3)]\n    hi = [max(b[1][i] for b in parts.values()) for i in range(3)]\n    assert lo == [-w / 2, -d / 2, -h / 2] and hi == [w / 2, d / 2, h / 2]\n    s_lo, s_hi = parts["Shaft"]\n    # the front is local -Y (every Zoo prop\'s): the shaft stands back from it and its back is the wall, +Y\n    assert s_lo[1] == -d / 2 + P.SHAFT_BACK and s_hi[1] == d / 2\n    assert s_lo[0] == -w / 2 + P.SHAFT_INSET and s_hi[0] == w / 2 - P.SHAFT_INSET\n    # the shaft abuts the plinth\'s top and the cap\'s underside, and those two faces of it are dropped\n    assert s_lo[2] == parts["Plinth"][1][2] and s_hi[2] == parts["Cap"][0][2]\n    assert P.hidden("Shaft", (0, 0, 1)) and P.hidden("Shaft", (0, 0, -1))\n    assert not P.hidden("Shaft", (0, 1, 0)) and not P.hidden("Plinth", (0, 0, 1))\n\n\ndef test_it_is_the_buildings_stone_trim():\n    from zoo_keeper.core import dressing\n    g = genome.load_species("wall_pilaster")\n    assert g["materials"]["options"] == [dressing.STONE_TRIM_KIND]\n    assert all(tuple(s["color"]) == dressing.STONE_TRIM_COLOR for s in g["styles"].values())\n\n\n@pytest.mark.parametrize("corner", ("min", "default", "max"))\ndef test_bpy_the_pier_builds_with_no_coincident_faces(corner):\n    pytest.importorskip("bpy")\n    from tests.test_coincident_faces import _probe_species\n    rec = _probe_species("wall_pilaster", corner)\n    assert rec["pairs"] == [], rec["pairs"][:3]\n', 'zoo_keeper/core/pilaster_forms.py': '"""wall_pilaster\'s shape, pure: the boxes `recipes/wall_pilaster.py` builds and the faces it drops (1.150.0).\n\nA flat stone pier standing a hand proud of a civic wall, ground to cornice -- Deli Counter (>= 0.294.0) chooses where,\nfrom the wall\'s openings, and gives it a collider, so it is solid where a body walks. A plinth block at its foot, a\nshaft set back from it, a cap block under the cornice; one material, the building\'s stone trim\n(`dressing.STONE_TRIM_KIND`, `STONE_TRIM_COLOR`), so it reads as one stone with the string courses and the quoins.\n\nTHE ENVELOPE IS THE SLOT\'S, EXACTLY: plinth and cap span the slot\'s full width and depth; the shaft is `SHAFT_INSET`\nnarrower each side and stands `SHAFT_BACK` behind their front, its back on the slot\'s back face (the wall). It ABUTS\nthe plinth\'s top and the cap\'s bottom, so its own top and bottom faces are hidden and dropped: no two faces coincide.\nFrame: x across the pier, z up, centre pivot; the FRONT is local -Y, as every Zoo prop\'s is (Deli Counter turns a\nslot\'s +Y onto its bearing), so the wall is the +Y face.\n"""\nfrom __future__ import annotations\n\nPLINTH_H = 0.45\nPLINTH_MAX = 0.12          # of the height, for a short pier\nCAP_H = 0.25\nCAP_MAX = 0.06\nSHAFT_INSET = 0.03\nSHAFT_BACK = 0.02\n\n\ndef boxes(w: float, d: float, h: float):\n    """``[(name, lo, hi)]`` in the centre-pivot frame."""\n    hw, hd, hh = w / 2.0, d / 2.0, h / 2.0\n    ph = min(PLINTH_H, h * PLINTH_MAX)\n    ch = min(CAP_H, h * CAP_MAX)\n    back = min(SHAFT_BACK, d * 0.4)\n    inset = min(SHAFT_INSET, w * 0.2)\n    return [\n        ("Plinth", (-hw, -hd, -hh), (hw, hd, -hh + ph)),\n        ("Shaft", (-hw + inset, -hd + back, -hh + ph), (hw - inset, hd, hh - ch)),\n        ("Cap", (-hw, -hd, hh - ch), (hw, hd, hh)),\n    ]\n\n\ndef hidden(part: str, normal) -> bool:\n    """The shaft\'s top and bottom: the cap\'s underside and the plinth\'s top cover them."""\n    return part == "Shaft" and abs(normal[2]) > 0.9\n', 'zoo_keeper/genome/species/wall_pilaster.json': '{\n "species": "wall_pilaster",\n "version": 1,\n "license": {\n  "construction_knowledge": "CC0",\n  "notes": "Minted 2026-10-30 by tools/new_species.py from \'prop\': a placeholder box at the authored dims until the recipe is shaped. REFERENCE: a flat stone pier standing a hand proud of a civic wall, ground to cornice: a plinth block at its foot, a plain shaft, a cap block under the cornice; in the building\'s stone trim Shaped 2026-10-30 (Zoo 1.150.0): plinth, shaft, cap in the stone trim."\n },\n "dimensions": {\n  "width": {\n   "min": 0.24,\n   "max": 1.2,\n   "default": 0.6\n  },\n  "depth": {\n   "min": 0.04,\n   "max": 0.2,\n   "default": 0.1\n  },\n  "height": {\n   "min": 2.8,\n   "max": 14.0,\n   "default": 7.0\n  }\n },\n "parts": [\n  "WallPilaster_Plinth",\n  "WallPilaster_Shaft",\n  "WallPilaster_Cap"\n ],\n "params": {},\n "materials": {\n  "default": "plaster",\n  "options": [\n   "plaster"\n  ]\n },\n "styles": {\n  "default": {\n   "material": "plaster",\n   "color": [\n    0.8,\n    0.76,\n    0.68\n   ],\n   "wear": 0.15,\n   "bevel": 0.006\n  },\n  "delco": {\n   "material": "plaster",\n   "color": [\n    0.8,\n    0.76,\n    0.68\n   ],\n   "wear": 0.35,\n   "bevel": 0.006,\n   "ambient": 0.35\n  },\n  "center_city": {\n   "material": "plaster",\n   "color": [\n    0.8,\n    0.76,\n    0.68\n   ],\n   "wear": 0.122,\n   "bevel": 0.006,\n   "ambient": 0.15\n  },\n  "industrial_flats": {\n   "material": "plaster",\n   "color": [\n    0.8,\n    0.76,\n    0.68\n   ],\n   "wear": 0.57,\n   "bevel": 0.006,\n   "ambient": 0.45\n  },\n  "rockay": {\n   "material": "plaster",\n   "color": [\n    0.8,\n    0.76,\n    0.68\n   ],\n   "wear": 0.29,\n   "bevel": 0.006,\n   "ambient": 0.05\n  }\n },\n "budgets": {\n  "tris_lod0": 200\n },\n "attachments": [],\n "collision": true,\n "match_priority": 0,\n "keywords": [\n  "wall pilaster",\n  "pilaster",\n  "stone pier"\n ]\n}\n', 'zoo_keeper/recipes/wall_pilaster.py': '"""wall_pilaster recipe: a flat stone pier on a civic wall -- plinth, shaft, cap (1.150.0, the factory\'s roadmap 324).\n\nMinted 2026-10-30 by `tools/new_species.py`; shaped here. The vertical slice\'s bank had a 22 m flank of blank stucco\nbetween its corners. A pilaster used to be a Patina cover, proud of the wall with no collider, and was withdrawn for\nstanding in walkable space; carving piers into the wall modules cannot follow a bay line, because Deli Counter tiles\neach storey round its own openings and the storeys share almost no seams (the factory\'s docs/findings/slice_look/).\nSo a pilaster is a solid of its own, placed by Deli Counter and collided like any other.\n\nThe shape is `core/pilaster_forms.py`\'s. ONE MATERIAL, the plan\'s (the genome\'s stone trim). One collider, the slot\'s\nwhole box.\n"""\nfrom __future__ import annotations\n\nfrom ..bpylayer import geometry, materials\nfrom ..core.pilaster_forms import boxes, hidden\n\n\ndef build(plan, streams, collection):\n    w = plan["dimensions"]["width"]\n    d = plan["dimensions"]["depth"]\n    h = plan["dimensions"]["height"]\n    rng = streams.stream("wear")\n    objs = []\n    for name, lo, hi in boxes(w, d, h):\n        bm = geometry.new_bm()\n        geometry.add_box(bm, tuple((lo[i] + hi[i]) / 2.0 for i in range(3)), tuple(hi[i] - lo[i] for i in range(3)))\n        geometry.drop_faces(bm, lambda nrm, part=name: hidden(part, nrm))\n        objs.append(geometry.bm_to_object(bm, f"WallPilaster_{name}", collection, bevel=plan["bevel"], texel=1.2,\n                                          rng=rng, wear=plan["wear"]))\n    surface = materials.make_material(f"M_WallPilaster_{plan[\'material\']}", plan["color"], plan["material"])\n    materials.assign(objs, surface)\n    return {"objects": objs, "collision_boxes": [((-w / 2, -d / 2, -h / 2), (w / 2, d / 2, h / 2))],\n            "attachments": {"ATT_top": (0.0, 0.0, h / 2)}}\n'}


def _sha(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: %s/%s has mixed line endings; nothing written" % (REPO.name, name))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text) != PINS[name]:
        raise SystemExit("REFUSED: %s/%s is %s, not the %s this patch was written against; nothing written"
                         % (REPO.name, name, _sha(text), PINS[name]))
    return text, crlf > 0


def main():
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: %s/%s: the anchor at %s is there %d times; nothing written"
                                 % (REPO.name, name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name, text in WHOLE.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: %s/%s exists already; nothing written" % (REPO.name, name))
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).parent.mkdir(parents=True, exist_ok=True)
        (REPO / name).write_bytes(text.encode("utf-8"))
    print("%s: %d files edited, %d written" % (REPO.name, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main())
